{
  "name": "Typhos多行文本编辑组件",
  "name_en": "Typhos Text Edit Widget",
  "manufacturer": "",
  "description": "一个非物理实验软件界面组件，用于通过 PyDM 通道显示、编辑并提交多行文本内容。它可根据通道写权限切换为只读模式，适合在实验控制界面中输入或查看备注、配置文本或其他字符串数据。",
  "description_en": "A non-physical laboratory software UI component for displaying, editing, and sending multiline text through PyDM channels. It can switch to read-only mode based on channel write access, making it suitable for entering or viewing notes, configuration text, or other string data in experiment control interfaces.",
  "actions": [
    {
      "action_name": "auto-value_changed",
      "description": "接收新的通道值并更新文本显示",
      "description_en": "Receive a new channel value and update the text display"
    },
    {
      "action_name": "auto-send_value",
      "description": "发送当前文本到通道以更新数值",
      "description_en": "Send the current text to the channel to update the value"
    },
    {
      "action_name": "auto-write_access_changed",
      "description": "根据写入权限切换编辑器的只读状态",
      "description_en": "Change the editor read-only state based on write access"
    },
    {
      "action_name": "auto-set_display",
      "description": "设置文本编辑器的显示内容",
      "description_en": "Set the displayed content of the text editor"
    }
  ],
  "tag_hints": [
    "Typhos UI",
    "PyDM channel",
    "multiline text editing",
    "write access control",
    "Qt widget",
    "experiment control interface"
  ]
}

